<style lang="scss" scoped src="./pagination-report-table.scss"></style>

<script>
import { Component, Prop, Vue, Watch } from 'vue-property-decorator';
import { ButtonMode, ButtonSize } from '../button/button.constants';
import Button from '../button/button.vue';
import GmsConfigureReportModal from '../gms-configure-report-modal/gms-configure-report-modal';
import GmsNewReportModal from '../gms-new-report-modal/gms-new-report-modal';
import GmsSaveCustomViewModal from '../gms-save-custom-view-modal/gms-save-custom-view-modal.vue';
import GmsSendReportModal from '../gms-send-report-modal/gms-send-report-modal';
import { IconShape } from '../icon/icon.constants';
import PaginationTable from '../pagination-table/pagination-table';
import SearchButton from '../search-button/search-button';
import Select from '../select/select';
import { SELECT_REPORTS_STYLES } from '../select/select.constants';
import SelectionMenu from '../selection-menu/selection-menu';
import { SelectionMenuMode } from '../selection-menu/selection-menu.constants';
import { TableSortMode } from '../table-header-cell/table-header-cell.constants';

@Component({
  components: {
    Button,
    Select,
    SelectionMenu,
    SearchButton,
    PaginationTable,
    GmsNewReportModal,
    GmsConfigureReportModal,
    GmsSendReportModal,
    GmsSaveCustomViewModal
  }
})
export default class PaginationReportTable extends Vue {
  /**
   * Set this to true when you are loading stuff and you don't want the user
   * interacting with things or switching things.
   */
  @Prop({ type: Boolean, default: false })
  isLoading;

  /**
   * The current report (matched by "value" in the reports prop)
   */
  @Prop({
    type: [Boolean, String],
    default: ''
  })
  reportId;

  /**
   * This object contains EXACTLY the props that should be applied to a
   * GmsNewReportModal.
   *
   * See GmsNewReportModal for prop
   * details.
   */
  @Prop({ type: Object, default: () => ({}) }) newReport;

  /**
   * This object contains the EXACT events of GmsNewReportModal.
   *
   * See GmsNewReportModal component docs for event details.
   */
  @Prop({ type: Object, default: () => ({}) }) newReportEvents;

  /**
   * This object contains EXACTLY the props that should be applied to a
   * GmsSendMessageModal.
   *
   * See GmsSendMessageModal for prop
   * details.
   */
  @Prop({ type: Object, default: () => ({}) }) sendMessageProps;

  /**
   * This object contains EXACTLY the props that should be applied to a
   * GmsSaveCustomViewModal.
   *
   * See GmsSaveCustomViewModal for prop
   * details.
   */
  @Prop({ type: Object, default: () => ({}) }) saveCustomViewProps;
  /**
   * This object contains the EXACT events of GmsSaveCustomViewModal.
   *
   * See GmsSaveCustomViewModal component docs for event details.
   */
  @Prop({ type: Object, default: () => ({}) }) saveCustomViewEvents;

  /**
   * Provides the list of available reports
   *
   * Example values per array item:
   * {
   *   label : "Donors"
   *   value : "donors"
   *   icon : IconShape.Thing
   *   favourite : true
   *   mode : "primary"
   *   dataSrc : "donors" // Not necessary
   * }
   */
  @Prop({
    type: Array,
    default: () => []
  })
  reports;

  /**
   * Data column configuration.
   * Example item in the list of items:
   *
   * {
   *   name : "Donor"
   *   id : "donor"
   *   type : "name"
   *   align : "TableHeaderCell--left"
   *   size : "Table--large"
   *   mode : "Table--primary"
   *   sortable : true
   *   options : Special and complicated see next section
   * }
   *
   * Options for the header supports custom filter functions for the data in
   * each row:
   *
   * options: [{
   *   label: "A - G",
   *   filterFunc: data => {
   *     return (
   *       data.firstName.toLowerCase().localeCompare("a") === 1 &&
   *       data.firstName.toLowerCase().localeCompare("h") === -1
   *     );
   *   }
   * }]
   *
   * Options also support direct matching for filters:
   * options: [
   *   { label: "Active", value: "Active" },
   *   { label: "Complete", value: "Complete" },
   *   { label: "Expired", value: "Expired" },
   *   { label: "Transaction Failed", value: "Failed" }
   * ]
   */
  @Prop({ type: Array, default: () => [] })
  headers;

  /**
   * This populates the Table with the current data to show to the user. (The
   * table filters the data for you automatically so inject all data here)
   *
   * Example row of data:
   *
   * {
   *   data: {
   *     donor: {
   *       firstName: "Floyd",
   *       lastName: "Miles"
   *     },
   *     date: new Date(2021, 0, 4),
   *     type1: "Cash",
   *     type2: "Cash",
   *     type3: "Cash",
   *     amount: {
   *       amount: 328.85,
   *       currency: CurrencyNotation.USD
   *     },
   *     frequency: "Monthly",
   *     status: TableCellStatus.ACTIVE,
   *     giving: {
   *       amount: 328.85,
   *       currency: CurrencyNotation.USD
   *     },
   *     campaign: "Enimu dui tristique at mass"
   *   },
   *   warning: false
   * },
   *
   * Note inside "data" the keys in the object matches the ids of the columns
   * defined in the header, then you inject the appropriate data.
   */
  @Prop({ type: Array, default: () => [] })
  rows;

  /**
   * The list of rows per page options.
   * Each option should include one label and its number value
   *
   * [
   *   label: string;
   *   value: number;
   * ]
   */
  @Prop({
    type: Array,
    default: () => []
  })
  rowsPerPageOptions;

  @Prop({
    type: Number,
    default: 10
  })
  defaultRowsPerPage;

  /**
   * The list of download formats.
   * Each option should include one label and its value
   *
   * [
   *   label: string;
   *   value: string;
   * ]
   */
  @Prop({
    type: Array,
    default: () => []
  })
  downloadFormats;

  @Prop({
    type: String,
    default: ''
  })
  defaultFormat;

  @Prop({
    type: Number,
    default: 0
  })
  totalPageNumber;

  @Prop({
    type: Number,
    default: 1
  })
  currentPage;

  @Prop({
    type: String,
    default: ''
  })
  searchValue;

  @Prop({ type: Boolean, default: false })
  loadingNewData;

  @Prop({ type: Boolean, default: false })
  multiFilter;

  @Prop({ type: Number, default: 0 })
  recordCount;

  @Prop({ type: Boolean, default: false })
  canDelete;

  @Prop({ type: Boolean, default: true })
  rollUpAllLocations;

  @Prop({ type: Boolean, default: false })
  isDefaultReport;

  @Prop({ type: Number, default: 10 })
  paginationLimit;

  @Prop({ type: String, default: '' })
  focus;

  @Prop({
    type: Array,
    default: () => []
  })
  initialFilters;

  @Watch('reportId')
  onReportIdChange(id) {
    this.currentReport = this.reports.find(
      report => report.value === this.reportId
    );
    this.hasNewChanges = false;
    if (id) {
      this.initConfig();
    }
  }

  config = {
    sortId: undefined,
    sortMode: TableSortMode.NO_SORT,
    sortFunc: undefined,
    currentPage: 0,
    rowsPerPage: 10,
    enableFilter: false,
    filters: new Map(),
    searchValue: '',
    headers: []
  };

  newReportError = '';

  // Enums
  ButtonMode = ButtonMode;
  ButtonSize = ButtonSize;
  IconShape = IconShape;
  SelectionMenuMode = SelectionMenuMode;

  showNewReport = false;
  openConfigureReport = false;
  hasNewChanges = false;
  downloadFormat = false;

  // report
  currentReport = { label: undefined, value: undefined };

  beforeMount() {
    this.downloadFormat = this.defaultFormat;
    this.currentReport = this.reports.find(
      report => report.value === this.reportId
    );

    // required to show initial columns
    this.config.headers = this.headers.map(({ name, id, display }) => ({
      name,
      id,
      display
    }));
  }

  initConfig() {
    this.config = {
      sortId: undefined,
      sortMode: TableSortMode.NO_SORT,
      sortFunc: undefined,
      currentPage: 0,
      rowsPerPage: this.defaultRowsPerPage,
      enableFilter: false,
      filters: new Map(),
      searchValue: '',
      headers: []
    };

    for (let i = 0; i < this.headers.length; i++) {
      const header = this.headers[i];
      const filterOptions = header.filterOptions || [];

      if (filterOptions) {
        for (let j = 0; j < filterOptions.length; j++) {
          filterOptions[j].selected = true;
        }
      }

      this.config.filters.set(header.id, {
        searchWord: '',
        options: filterOptions
      });
    }
  }

  // handlers
  handleReportChange(val, report) {
    if (!this.currentReport || this.currentReport.value !== val) {
      /**
       * Emits when the user selects a new report to display from the report
       * dropdown.
       *
       * @event reportChange
       */
      this.$emit('reportChange', val, report, this.config);
    }
  }

  handleAddReport() {
    this.showNewReport = true;
    /**
     * Emits when the user requests to make a new report
     *
     * @event newReport
     */
    this.$emit('newReport');
  }

  handleSearch(word) {
    /**
     * Emits when the user specifies a new custom search
     *
     * @event search
     */
    this.$emit('search', word);
  }

  handleRefresh() {
    /**
     * Emits when the user requests a refresh on their current report
     *
     * @event refresh
     */
    this.$emit('refresh', this.config);
  }

  handleForward() {
    /**
     * Emits when the user clicks the forwarding control
     *
     * @event forward
     */
    this.$emit('forward');
  }

  handleDownload() {
    /**
     * Emits when the user clicks the download control
     *
     * @event download
     */
    this.$emit('download', this.downloadFormat);
  }

  handleDownloadFormatChange(format) {
    this.downloadFormat = format;
  }

  handleCloseNewReportModal() {
    this.showNewReport = false;
    /**
     * Emits when the user closes the new report modal
     *
     * @event closeNewReport
     */
    this.$emit('closeNewReport');
  }

  handleCloseSendReportModal() {
    /**
     * Emits when the user closes the send message modal
     *
     * @event closeSendMessage
     */
    this.$emit('closeSendMessage');
  }

  handleEnableFilter() {
    this.config.enableFilter = !this.config.enableFilter;
    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
  }

  handleInput(value) {
    if (value !== this.config.searchValue) {
      this.config.searchValue = value;
      /**
       * Emits when the user request new data after filter or pagination.
       * @event request
       */
      this.$emit('request', this.config, true);
    }
  }

  handleOpenConfigureReport() {
    /**
     * Emits when user opens configure report view
     * @event openConfigureReportView
     */
    this.$emit('openConfigureReportView');
    this.openConfigureReport = true;
  }

  handleCloseConfigureReport() {
    /**
     * Emits when user closes configure report view
     * @event closeConfigureReportView
     */
    this.$emit('closeConfigureReportView');
    this.openConfigureReport = false;
  }

  handleSwitchRollUp(value) {
    /**
     * Emits when the user switches roll up state
     *
     * @event rollUp
     */
    this.$emit('rollUp', value);
  }

  handleMakeDefault() {
    this.$emit('makeDefault');
    this.openConfigureReport = false;
  }

  handleDeleteReport() {
    /**
     * Emits when user clicks delete report
     * @event deleteReport
     */
    this.$emit('deleteReport');
    this.openConfigureReport = false;
  }

  /**
   * Handles when the user clicks the apply button.
   * The apply button can only be clicked when changes are made.
   * `allChanges` is an array that contains the new config in this order:
   * [columns, rollUp, reportName, visibility, active filters]
   */
  handleConfigChange(...allChanges) {
    /**
     * Emits when the user applies change to the report configuration
     * @event configChange
     */
    this.$emit('configChange', ...allChanges);
    this.hasNewChanges = true;
    this.openConfigureReport = false;
  }

  handleRequest(config, forceUpdate) {
    /**
     * Emits when the user request new data after filter or pagination.
     * @event request
     */
    Object.assign(this.config, config);
    this.$emit('request', this.config, forceUpdate);
  }

  handleFocusChange(focus) {
    /**
     * Emits when the user changes the focus applied to the report
     *
     * @event focusChange
     */
    this.$emit('focusChange', focus);
  }

  handleFilterChange(filters) {
    /**
     * Emits when the user changes the filters applied to the report
     *
     * @event filterChange
     */
    this.$emit('filterChange', filters);
  }

  handleSaveCheck(config) {
    if (!config.reportName) {
      this.newReportError = 'No Report Name';
      return false;
    }

    this.newReportError = '';
    return true;
  }

  handleSaveNewReport(config) {
    /**
     * Emits when the user clicks Save as a New Report
     *
     * @event saveNewReport
     */
    this.$emit('saveNewReport', config);
  }

  handleSaveReport() {
    this.showSaveCustomView = true;
    /**
     * Emits when the user requests to save a report
     *
     * @event saveReport
     */
    this.$emit('saveReport');
  }

  showSaveCustomView = false;

  handleCloseSaveCustomViewModal() {
    this.showSaveCustomView = false;
    /**
     * Emits when the user closes the save custome view modal
     *
     * @event closeSaveCustomView
     */
    this.$emit('closeSaveCustomView');
  }

  handleSaveOverCurrent(reportInfo) {
    /**
     * Emits when the user clicks Save Over Current Report button
     *
     * @event saveOverCurrentReport
     */
    this.$emit('saveOverCurrentReport', reportInfo, this.headers);

    this.hasNewChanges = false;
    this.showSaveCustomView = false;
  }

  handleSaveCustomView(reportInfo) {
    /**
     * Emits when the user clicks Save a custom view as a new report
     *
     * @event saveCustomView
     */
    this.$emit('saveCustomView', reportInfo, this.headers);

    this.hasNewChanges = false;
    this.showSaveCustomView = false;
  }

  get selectReportStyles() {
    return SELECT_REPORTS_STYLES;
  }
}
</script>

<template>
  <div class="PaginationReportTable">
    <div class="PaginationReportTable__Content">
      <div class="PaginationReportTable__Nav">
        <div class="PaginationReportTable__NavLeft">
          <div
            :class="[
              'PaginationReportTable--right-margin',
              'PaginationReportTable__SelectionMenu'
            ]"
          >
            <Select
              search
              label="Select a Report"
              :value="reportId"
              :items="reports"
              :itemStyle="selectReportStyles.itemStyle"
              :triggerStyle="selectReportStyles.triggerStyle"
              @select="handleReportChange"
            />
          </div>
          <div class="PaginationReportTable--right-margin">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.REFRESH"
              :iconSize="23"
              @click="handleRefresh"
            />
          </div>
          <div
            :class="[
              'PaginationReportTable__NewReport',
              'PaginationReportTable--right-margin'
            ]"
          >
            <Button
              v-if="hasNewChanges"
              :mode="ButtonMode.PRIMARY"
              :size="ButtonSize.GMS_LARGE"
              label="Save this Report"
              @click="handleSaveReport"
            />
            <Button
              v-else
              :mode="ButtonMode.GMS_ICON_LABEL"
              :icon="IconShape.PLUS"
              :iconSize="7"
              label="New Report"
              @click="handleAddReport"
            />
          </div>
        </div>
        <div class="PaginationReportTable__NavRight">
          <div class="PaginationReportTable__SearchButton">
            <SearchButton @input="handleInput" :value="searchValue" />
          </div>
          <div class="PaginationReportTable--left-margin">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.FILTER_LIST"
              :iconSize="23"
              @click="handleEnableFilter"
            />
          </div>
          <div class="PaginationReportTable--left-margin">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.FRAME"
              :iconSize="23"
              @click="handleOpenConfigureReport"
            />
          </div>
          <div class="PaginationReportTable--left-margin">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.REPLY"
              :iconSize="23"
              @click="$emit('showSendMessage')"
            />
          </div>
          <div class="PaginationReportTable--left-margin">
            <Button
              :mode="ButtonMode.GMS_ICON"
              :icon="IconShape.DOWNLOAD"
              :iconSize="23"
              @click="handleDownload"
            />
          </div>
          <div class="PaginationReportTable--left-margin">
            <Select
              search
              class="PaginationReportTable__FormatsMenu"
              label="Format"
              :value="downloadFormat"
              :items="downloadFormats"
              @select="handleDownloadFormatChange"
            />
          </div>
        </div>
      </div>
      <div class="PaginationReportTable__Table" ref="pagination-table">
        <PaginationTable
          :headers="headers"
          :rows="rows"
          :isLoading="isLoading"
          :enableFilter="this.config.enableFilter"
          :searchValue="searchValue"
          :rowsPerPageOptions="rowsPerPageOptions"
          :defaultRowsPerPage="defaultRowsPerPage"
          :totalPageNumber="totalPageNumber"
          :paginationLimit="paginationLimit"
          :currentPage="currentPage"
          :loadingNewData="loadingNewData"
          :reportId="reportId"
          :multiFilter="multiFilter"
          @goToCampaigns="$emit('goToCampaigns')"
          @request="handleRequest"
          @rowClicked="row => $emit('rowClicked', row)"
        />
      </div>
    </div>
    <GmsNewReportModal
      v-if="showNewReport"
      v-bind="newReport"
      v-on="newReportEvents"
      :showRecordCount="false"
      :recordCount="recordCount"
      :onSave="handleSaveCheck"
      :error="newReportError"
      @focusChange="handleFocusChange"
      @filterChange="handleFilterChange"
      @saveReport="handleSaveNewReport"
      @close="handleCloseNewReportModal"
    />
    <GmsConfigureReportModal
      v-if="openConfigureReport"
      :focus="focus"
      :headers="headers"
      :isDefaultReport="isDefaultReport"
      :canDelete="canDelete"
      :initialRollUp="rollUpAllLocations"
      :initialReportTitle="currentReport.label"
      :initialVisibility="
        currentReport.visibility || newReport.visibilityConfig.options[0].value
      "
      :visibilityConfig="newReport.visibilityConfig"
      :initialFilters="initialFilters"
      :filterConfig="newReport.filterConfig"
      @onFiltersChanged="filter => $emit('onFiltersChanged', filter)"
      @focusChange="handleFocusChange"
      @configChange="handleConfigChange"
      @close="handleCloseConfigureReport"
      @delete="handleDeleteReport"
      @switchRollUp="handleSwitchRollUp"
      @makeDefault="handleMakeDefault"
    />
    <GmsSendReportModal
      v-if="sendMessageProps.showSendMessage"
      v-bind="sendMessageProps"
      :schedule="currentReport.subscribers[0] || {}"
      @close="handleCloseSendReportModal"
      @addEmail="email => $emit('addEmail', email)"
      @removeEmail="index => $emit('removeEmail', index)"
      @send="schedule => $emit('send', schedule)"
      @sendOnce="recipients => $emit('sendOnce', recipients)"
      @deleteSchedule="() => $emit('deleteSchedule')"
    />
    <GmsSaveCustomViewModal
      v-if="showSaveCustomView"
      v-bind="saveCustomViewProps"
      v-on="saveCustomViewEvents"
      :canOverwrite="canDelete"
      :currentReport="currentReport"
      @close="handleCloseSaveCustomViewModal"
      @saveOverCurrentReport="handleSaveOverCurrent"
      @saveNewReport="handleSaveCustomView"
    />
  </div>
</template>
